package android.view.accessibility;public class AccessibilityEvent{public static final int TYPE_VIEW_CLICKED=1,TYPE_WINDOW_STATE_CHANGED=32,TYPE_WINDOW_CONTENT_CHANGED=2048,TYPE_WINDOWS_CHANGED=4194304,TYPE_VIEW_SCROLLED=4096;public int type,window=1;public long time;public java.util.List<CharSequence> text=new java.util.ArrayList<>();public long getEventTime(){return time;}public java.util.List<CharSequence> getText(){return text;}public CharSequence pkg,name;public AccessibilityNodeInfo source;public java.util.function.Supplier<AccessibilityNodeInfo> sourceLookup;public int getEventType(){return type;}public CharSequence getPackageName(){return pkg;}public CharSequence getClassName(){return name;}public int getWindowId(){return window;}public AccessibilityNodeInfo getSource(){return sourceLookup==null?source:sourceLookup.get();}public static AccessibilityEvent obtain(AccessibilityEvent e){AccessibilityEvent c=new AccessibilityEvent();c.type=e.type;c.window=e.window;c.pkg=e.pkg;c.name=e.name;c.source=e.source;c.sourceLookup=e.sourceLookup;c.time=e.time;c.text.addAll(e.text);return c;}public void recycle(){}}